151	        String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
152	        String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);
153	
154	        if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
155	            LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
156	            return false;
157	        }
158	
159	        try {
160	            JSONObject requestBody = new JSONObject();
161	            requestBody.put("code", code);
162	            requestBody.put("redirect_uri", redirectUri);
163	            requestBody.put("grant_type", "authorization_code");
164	            requestBody.put("client_id", jiraCID);
165	            requestBody.put("client_secret", jiraClientSecret);
166	
167	            String authExchangeResponse = new HttpURLConnectionInvoker(true).invokePostHttpURLConnWithRequestBody(
168	                    authExchangeUrl,
169	                    null,
170	                    null,
171	                    requestBody
172	            );
173	            LOGGER.log(Level.INFO, authExchangeResponse);
174	            JSONObject authExchangeJSONResponse = new JSONObject(authExchangeResponse);
175	
176	            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
177	            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
178	            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
179	            String jiraScope = authExchangeJSONResponse.optString("scope", null);
180	
181	            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
182	                return false;
183	            }
184	            addOrUpdateJiraAuth(projectId, zsoId, jiraAccessToken, jiraRefreshToken);
185	
186	            return true;
187	        } catch (Exception e) {
188	            LOGGER.log(Level.SEVERE, "Exception while authenticating Jira", e);
189	        }
190	        return false;
191	    }
