193	    public List<JiraSites> getJiraSites(String zsoId, Long projectId) {
194	        try {
195	            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
196	            if (jiraAuth == null) {
197	                return null;
198	            }
199	
200	            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
201	                if (CommonUtil.isEmpty(token)) {
202	                    return null;
203	                }
204	                String accessibleResourcesUrl = JIRA_BASE_URL + "/oauth/token/accessible-resources";
205	
206	                Map<String, String> headers = new HashMap<>();
207	                headers.put("Authorization", "Bearer " + token);
208	                headers.put("Accept", "application/json");
209	                LOGGER.log(Level.INFO , "Token {0}", token);
210	                try {
211	                    String accessibleResourcesResponse = new HttpURLConnectionInvoker(true)
212	                            .invokeGetHttpURLConn(
213	                                    accessibleResourcesUrl,
214	                                    headers,
215	                                    null
216	                            );
217	                    return new JSONObject(accessibleResourcesResponse);
218	                } catch (Exception e) {
219	                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
220	                }
221	                return null;
222	            });
223	
224	            if (jiraResponse == null) {
225	                return null;
226	            }
227	
228	            ArrayList<JiraSites> sites = new ArrayList<>();
229	
230	            JSONArray resourcesArray = jiraResponse.getJSONArray("data");
231	            for (int i = 0; i < resourcesArray.length(); i++) {
232	                JSONObject resource = resourcesArray.getJSONObject(i);
233	                JiraSites site = new JiraSites(
234	                        resource.getString("id"),
235	                        resource.getString("name")
236	                );
237	                sites.add(site);
238	            }
239	
240	            return sites;
241	
242	        } catch (Exception e) {
243	            LOGGER.log(Level.SEVERE, "Exception while fetching Jira sites", e);
244	        }
245	        return null;
246	    }
