559	    private JiraAuth getJiraAuth(
560	            String zsoId,
561	            long projectId
562	    ) {
563	        try {
564	            Criteria selectCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
565	            selectCriteria = selectCriteria.and(
566	                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
567	            );
568	
569	            Row jiraAuthRow = DBHandler.getFirstRowFromRedis(AppticsConstants.REFRESHTOKEN, selectCriteria, zsoId);
570	            if (jiraAuthRow != null) {
571	                return new JiraAuth(
572	                        zsoId,
573	                        projectId,
574	                        jiraAuthRow.getAs(AppticsConstants.ACCESSTOKEN, String.class),
575	                        jiraAuthRow.getAs(AppticsConstants.REFRESHTOKEN, String.class)
576	                );
577	            }
578	        } catch (Exception e) {
579	            LOGGER.log(Level.SEVERE, "Exception while fetch cloud id for project", e);
580	        }
581	        return null;
582	    }
