584	    private void addOrUpdateJiraAuth(
585	            long projectId,
586	            String zsoId,
587	            String accessToken,
588	            String refreshToken
589	    ) throws Exception {
590	        Map<String, Object> criteriaCols = new HashMap<>();
591	        criteriaCols.put(AppticsConstants.ZUID, projectId);
592	        criteriaCols.put(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
593	        if (MickeyUtil.isRowExist(
594	                AppticsConstants.REFRESHTOKEN,
595	                AppticsConstants.REFRESHTOKENID,
596	                criteriaCols,
597	                zsoId
598	        )) {
599	            LOGGER.log(Level.INFO, "Jira auth available for project already. Updating configs");
600	
601	            Criteria updateCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
602	            updateCriteria = updateCriteria.and(
603	                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
604	            );
605	
606	            Map<String, Object> updateColWithValue = new HashMap<>();
607	            updateColWithValue.put(AppticsConstants.REFRESHTOKEN, refreshToken);
608	            updateColWithValue.put(AppticsConstants.ACCESSTOKEN, accessToken);
609	            updateColWithValue.put(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());
610	
611	            DBHandler.updateInRedis(AppticsConstants.REFRESHTOKEN, updateCriteria, updateColWithValue, zsoId);
612	
613	        } else {
614	            Row authRow = new Row(AppticsConstants.REFRESHTOKEN);
615	            authRow.set(AppticsConstants.REFRESHTOKEN, refreshToken);
616	            authRow.set(AppticsConstants.ACCESSTOKEN, accessToken);
617	            authRow.set(AppticsConstants.ZUID, projectId);
618	            authRow.set(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
619	            authRow.set(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());
620	
621	            DBHandler.insertRedisCacheRow(
622	                    authRow,
623	                    AppticsConstants.REFRESHTOKEN,
624	                    AppticsConstants.REFRESHTOKENID,
625	                    zsoId
626	            );
627	        }
628	    }
