164		public JSONArray updateAndGetConfigurationByJUID(String tableName, Long juID) throws DataAccessException, JSONException
165		{
166	
167			SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
168			Criteria c = new Criteria(Column.getColumn(tableName, AppticsConstants.JUID), juID, QueryConstants.EQUAL);
169			c = c.and(new Criteria(Column.getColumn(tableName, AppticsConstants.STATUS), true, QueryConstants.EQUAL));
170			sq.addSelectColumn(Column.getColumn(tableName, "*"));
171			if (c != null)
172			{
173				sq.setCriteria(c);
174			}
175	
176			DataObject dobj = DBHandler.getPersistence().get(sq);
177			if (!dobj.containsTable(tableName))
178			{
179				return null;
180			}
181			JSONArray configArray = new JSONArray();
182			@SuppressWarnings("unchecked")
183			Iterator<Row> rows = dobj.getRows(tableName);
184			while (rows.hasNext())
185			{
186				JSONObject configs = new JSONObject();
187				Row row = rows.next();
188				if(tableName.equalsIgnoreCase("MessengerIntegrations"))
189				{
190					long aaid = (long) row.get(AppticsConstants.AAID);
191					String service = (String) row.get(AppticsConstants.SERVICE);
192					long projectId = AppHandler.getInstance().getProjectIDByAAID(aaid);
193					String projectName = ProjectHandler.getDisplayName(projectId);
194					updateStatusForAaid(tableName, service, aaid, false);
195					configs.put("service", service);
196					configs.put("projectName", projectName);
197					configs.put("projectId", projectId);
198				}
199				else
200				{
201					long apid = (long) row.get(AppticsConstants.APID);
202					String service = null;
203					if(tableName.equalsIgnoreCase("Integration"))
204					{
205						 service = (String) row.get("ServiceName");
206					}
207					else
208					{
209						service = tableName.split("I")[0];
210					}
211					long projectId = AppHandler.getInstance().getProjectID(apid);
212					String projectName = ProjectHandler.getDisplayName(projectId);
213					updateStatus(tableName, apid, false);
214					configs.put("service", service);
215					configs.put("projectName", projectName);
216					configs.put("projectId", projectId);
217				}
218				configArray.put(configs);
219			}
220			return configArray;
221		}
