49		public List<Object> checkAndGetAccessToken(String ipAddress, String userAgent, Long orgID) throws  IAMException
50		{
51			
52			TransactionManager txMgr = DBHandler.getTxnMgr();
53			String tableName = "BDaasOAuth";
54			
55			Long currentTime = System.currentTimeMillis();
56			String accessToken = null;
57			Long expiryTime = null;
58			
59			try {
60				Boolean isThisTrans = false;
61				if(txMgr.getStatus() != AppticsConstants.TRANSACTION_STATUS_ACTIVE) 
62				{
63					LOGGER.info("begining transaction to fetch accesstoken from properties table.");
64					txMgr.begin();
65					isThisTrans = true;
66				}
67				
68				SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
69				sq.addSelectColumn(Column.getColumn(tableName, "*"));
70		
71				Criteria c = new Criteria(Column.getColumn(tableName, "OrgID"), orgID, QueryConstants.EQUAL, false);
72				sq.setCriteria(c);
73		
74				sq.setLock(true);  
75				//This will lock the selected-row till this transaction is completed. Any other trans will wait for this to either commit or rollback.
76				
77				Persistence p = ADBHandler.getPersistence();
78				DataObject dobj = p.get(sq);
79				
80				Row row = dobj.getFirstRow(tableName);
81				expiryTime = (Long) row.get("ExpiryTime");
82				
83				if(currentTime < expiryTime)
84				{
85					row = dobj.getFirstRow(tableName);
86					LOGGER.log(Level.INFO, "Access token available in table..");
87					accessToken = (String) row.get("AccessToken");
88				}
89				
90				if(CommonUtil.isEmpty(accessToken)) 
91				{
92					String rfToken = (String) row.get("RefreshToken");
93					LOGGER.log(Level.INFO, "Generating new access token, with Refreshtoken : {0}, SOID : {1}, CLIENTID : {2}", new Object[] {rfToken, orgID, CLIENTID});
94					accessToken = IAMProxy.getInstance().getOAuthAPI().generateInternalOAuthAccessToken(CLIENTID, orgID, rfToken, AppticsConstants.JPROXY, ipAddress, userAgent);
95					
96					expiryTime = getEpochTime(currentTime); 
97					
98					LOGGER.info("Updating new access token at, updateTime : "+currentTime+", expiryTime : "+expiryTime);
99					
100					row.set("AccessToken", accessToken);
101					row.set("ExpiryTime", expiryTime);
102					dobj.updateRow(row);
103					p.update(dobj);
104				}
105				if(isThisTrans)
106				{
107					txMgr.commit();	
108				}
109				
110				
111			}
112			catch(Exception e) 
113			{
114				LOGGER.log(Level.SEVERE, "Exception while getting/setting access token : {0}", e);
115				try {
116					txMgr.rollback();
117				} catch (IllegalStateException | SecurityException | SystemException e1) {
118					LOGGER.log(Level.SEVERE, "Exception while txMgr rollback : {0}", e1);
119				}
120			}
121			
122			if(CommonUtil.isEmpty(accessToken) || CommonUtil.isEmpty(expiryTime))
123			{
124				LOGGER.log(Level.SEVERE, "Either accessToken or expiryTime is null");
125				return null;
126			}
127			
128			List<Object> result = new ArrayList<Object>();
129			result.add(accessToken);
130			result.add(expiryTime);
131			return result;
132			
133		}
