135		public static String getAccessToken(String serviceName, String clientID, long zuid, String loginname, String[] scope)
136		{
137			if(CommonUtil.isEmpty(clientID))
138			{
139				LOGGER.log(Level.INFO, "Client ID is empty.");
140				return null;
141			}
142			try
143			{
144				SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.REFRESHTOKEN));
145				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID));
146				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKEN));
147				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ACCESSTOKEN));
148				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.EXPAIREDTIME));
149				
150				Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID),zuid, QueryConstants.EQUAL);
151				c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), serviceName, QueryConstants.EQUAL, false));
152				
153				sq.setCriteria(c);
154				
155				DataObject dobj = DBHandler.getPersistence(loginname).get(sq);
156				
157				if (!dobj.containsTable(AppticsConstants.REFRESHTOKEN))
158				{
159					LOGGER.log(Level.INFO, "No Rows found match with zuid = ");
160					return null;
161				}
162				
163				Row r = dobj.getFirstRow(AppticsConstants.REFRESHTOKEN);
164				String refreshToken = (String) r.get(AppticsConstants.REFRESHTOKEN);
165				if(CommonUtil.isEmpty(refreshToken))
166				{
167					LOGGER.log(Level.INFO, "Getting refreshtoken as null for the user = ");
168					return null;
169				}
170				String accessToken = (String) r.get(AppticsConstants.ACCESSTOKEN);
171				Long expairedTime = (Long) r.get(AppticsConstants.EXPAIREDTIME);
172				if(!CommonUtil.isEmpty(accessToken, expairedTime) && CalendarUtil.currentTimeMillis() < expairedTime)
173				{
174					LOGGER.log(Level.INFO, "Returning the stored access token for the user.");
175					return accessToken;
176				}
177	
178				accessToken = generateAccessToken(clientID, refreshToken, zuid, scope, serviceName);
179				if(CommonUtil.isEmpty(accessToken))
180				{
181					LOGGER.log(Level.INFO, "Genarated access token as null for the user = ");
182					return null;
183				}
184	
185				expairedTime = CalendarUtil.currentTimeMillis() + (59*60*1000);
186				updateAccessToken(serviceName, zuid, accessToken, loginname, expairedTime);
187				return accessToken;
188			}
189			catch(DataAccessException e)
190			{
191				LOGGER.log(Level.SEVERE, "Exception while fetch refresh and access token.", e);
192			}
193			return null;
194		}
